const menuButton=document.querySelector(".menu-toggle"),nav=document.querySelector("#menu-principal"),submenuButton=document.querySelector(".submenu-toggle"),submenuItem=document.querySelector(".submenu-item");function fecharSubmenu(){submenuButton.setAttribute("aria-expanded","false"),submenuItem.classList.remove("is-open")}function fecharMenu(){menuButton.setAttribute("aria-expanded","false"),nav.classList.remove("is-open"),fecharSubmenu()}menuButton.addEventListener("click",()=>{const open="true"!==menuButton.getAttribute("aria-expanded");menuButton.setAttribute("aria-expanded",String(open)),nav.classList.toggle("is-open",open),open||fecharSubmenu()}),submenuButton.addEventListener("click",()=>{const open="true"!==submenuButton.getAttribute("aria-expanded");submenuButton.setAttribute("aria-expanded",String(open)),submenuItem.classList.toggle("is-open",open)}),nav.addEventListener("click",event=>{event.target.closest("a")&&fecharMenu()}),document.addEventListener("keydown",event=>{if("Escape"!==event.key)return;const focoNoSubmenu=submenuItem.contains(document.activeElement);fecharMenu(),focoNoSubmenu&&submenuButton.focus()}),document.addEventListener("click",event=>{submenuItem.contains(event.target)||fecharSubmenu(),event.target.closest("header")||fecharMenu()}),window.addEventListener("resize",()=>{window.innerWidth>=600&&fecharMenu()});